import { stackColumns } from "@/config/content";

function Stack() {
  return (
    <section
      id="stack"
      className="mx-auto max-w-[1280px] px-6 pt-22 pb-10 md:px-10"
    >
      <h6 className="mb-3.5 text-[var(--tb-ink-accent)]">03 — Stack</h6>
      <h2 className="mb-10 text-[2.875rem] tracking-[-0.02em]">
        TOOLS WE ACTUALLY USE
      </h2>

      <div className="border-border bg-border grid grid-cols-1 gap-px border sm:grid-cols-3">
        {stackColumns.map((column) => (
          <div key={column.label} className="bg-background px-6 py-7 pb-7.5">
            <div className="mb-4.5 flex items-center gap-2.5">
              <span
                className={
                  column.filled
                    ? "bg-primary size-2.5"
                    : "border-foreground size-2.5 border"
                }
              />
              <span className="font-mono text-[11px] tracking-[0.18em] uppercase">
                {column.label}
              </span>
            </div>
            <div className="flex flex-wrap gap-2 font-mono text-[13px]">
              {column.tools.map((tool) => (
                <span
                  key={tool}
                  className="border-border border px-2.5 py-1.25"
                >
                  {tool}
                </span>
              ))}
            </div>
          </div>
        ))}
      </div>
    </section>
  );
}

export { Stack };
