import Link from "next/link";

import { Blueprint } from "@/components/blueprint/blueprint";
import { MatrixRain } from "@/components/effects/matrix-rain";
import { Terminal } from "@/components/effects/terminal";
import { Button } from "@/components/ui/button";
import { heroIndex } from "@/config/content";
import { siteConfig } from "@/config/site";

function Hero() {
  return (
    <section
      id="top"
      className="border-border relative overflow-hidden border-b"
    >
      <div
        aria-hidden="true"
        className="absolute inset-0"
        style={{
          backgroundImage:
            "linear-gradient(to right, color-mix(in srgb, var(--foreground) 5%, transparent) 1px, transparent 1px), linear-gradient(to bottom, color-mix(in srgb, var(--foreground) 5%, transparent) 1px, transparent 1px)",
          backgroundSize: "80px 80px",
        }}
      />

      <MatrixRain density={siteConfig.rainDensity} motion={siteConfig.motion} />

      <div
        aria-hidden="true"
        className="font-heading text-primary pointer-events-none absolute right-[-1.5vw] bottom-[-6vw] text-[30vw] leading-[0.78] font-semibold opacity-[0.07] select-none"
        style={{ letterSpacing: "-0.04em" }}
      >
        10
      </div>

      <div className="relative mx-auto grid max-w-[1280px] grid-cols-1 items-center gap-16 px-6 py-24 pb-18 md:grid-cols-[1.05fr_0.95fr] md:px-10">
        <div>
          <div className="mb-6.5 flex items-center gap-3 font-mono text-[11px] tracking-[0.22em] text-[var(--tb-ink-accent)] uppercase">
            <span className="bg-primary h-px w-10" />
            <span>Two bits · four states · one team</span>
          </div>

          <h1 className="mb-6 text-[clamp(3.5rem,6.4vw,6rem)] leading-[0.92] font-semibold tracking-[-0.025em] text-balance">
            <span className="block">
              WE BUILD THE{" "}
              <span className="relative inline-block text-[var(--tb-ink-accent)]">
                1
                <span className="bg-primary absolute inset-x-0 bottom-[0.1em] h-1.5" />
              </span>
              .
            </span>
            <span className="block">
              WE BREAK THE{" "}
              <span className="relative inline-block text-[var(--tb-ink-accent)]">
                0
                <span className="bg-primary absolute inset-x-0 bottom-[0.1em] h-1.5" />
              </span>
              .
            </span>
          </h1>

          <p className="text-foreground/78 mb-8.5 max-w-[46ch] text-[19px] leading-relaxed">
            {siteConfig.description}
          </p>

          <div className="mb-11 flex items-center gap-3">
            <Blueprint>
              <Button
                size="lg"
                nativeButton={false}
                className="px-6.5 py-3.5 text-[15px] tracking-wide"
                render={<Link href="#contact">START A PROJECT</Link>}
              />
            </Blueprint>
            <Button
              variant="outline"
              size="lg"
              nativeButton={false}
              className="px-5.5 py-3.5 text-[15px] tracking-wide"
              render={<Link href="#services">SEE THE FOUR SERVICES</Link>}
            />
          </div>

          <div className="border-border bg-border grid max-w-[560px] grid-cols-2 gap-px border sm:grid-cols-4">
            {heroIndex.map((item) => (
              <div key={item.code} className="bg-background px-4 py-3.5">
                <div className="mb-1 font-mono text-[10px] text-[var(--tb-ink-accent)]">
                  {item.code}
                </div>
                <div className="font-heading text-[15px]">{item.label}</div>
              </div>
            ))}
          </div>
        </div>

        <div className="animate-tb-rise">
          <Terminal />
        </div>
      </div>
    </section>
  );
}

export { Hero };
