import Link from "next/link";
import type { CSSProperties } from "react";

import { Blueprint } from "@/components/blueprint/blueprint";
import { ScrambleLink } from "@/components/effects/scramble-text";
import { ThemeToggle } from "@/components/theme/theme-toggle";
import { Button } from "@/components/ui/button";
import { navItems, siteConfig } from "@/config/site";

function SiteHeader() {
  return (
    <header className="border-border bg-background/88 sticky top-0 z-40 border-b backdrop-blur-md">
      <div
        data-tb-nav
        className="mx-auto flex max-w-[1280px] items-center gap-4 px-[clamp(1.125rem,3vw,2.5rem)] py-3.5 md:gap-10"
      >
        <Link
          href="#top"
          className="text-foreground mr-auto flex items-center gap-3 no-underline"
        >
          <span className="flex gap-1">
            <span className="bg-primary h-6.5 w-3.5" />
            <span className="border-foreground h-6.5 w-3.5 border" />
          </span>
          <span className="font-heading text-xl font-semibold tracking-wide">
            {siteConfig.name.toUpperCase()}
          </span>
        </Link>

        <nav
          data-tb-navlinks
          className="font-heading text-foreground flex flex-wrap items-center gap-[clamp(0.875rem,2vw,1.75rem)] text-[13px] tracking-wider uppercase"
        >
          {navItems.map((item) => (
            <ScrambleLink
              key={item.href}
              href={item.href}
              className="hover:text-primary text-inherit no-underline transition-colors"
            >
              {item.label}
            </ScrambleLink>
          ))}
        </nav>

        <ThemeToggle />

        <Blueprint>
          <Button
            size="lg"
            nativeButton={false}
            className="text-[13px] tracking-wide"
            render={<Link href="#contact">START A PROJECT</Link>}
          />
        </Blueprint>
      </div>

      <div
        aria-hidden="true"
        className="animate-tb-prog bg-primary h-0.5 origin-left"
        style={{ animationTimeline: "scroll(root block)" } as CSSProperties}
      />
    </header>
  );
}

export { SiteHeader };
